queries.queryString:
_view=sumologic_search_usage_per_query {{{filter}}}
//( query_type=*view*)

| if(execution_duration_ms < 1000 * {{slow_seconds}},1,0) as fast
| sum(fast) as fast

_view=sumologic_search_usage_per_query {{{filter}}}
//( query_type=*view*)

| if(execution_duration_ms < 1000 * {{slow_seconds}},0,1) as slow
| sum(slow) as slow

_view=sumologic_search_usage_per_query {{{filter}}}
| timeslice by {{timeslice}}
|if(execution_duration_ms < 1000 * {{slow_seconds}},0,1) as slow
| sum(slow) as slow, count as all by _timeslice | all-slow as fast | fields _timeslice,slow,fast

_view=sumologic_search_usage_per_query {{{filter}}}
| timeslice by {{timeslice}}
| execution_duration_ms / 1000 as execution_duration_s
| pct(execution_duration_s,50) by query_type,_timeslice |transpose row _timeslice column query_type

_view=sumologic_search_usage_per_query {{{filter}}}
| where execution_duration_ms > (1000 * {{slow_seconds}})
| timeslice by {{timeslice}}
|if(execution_duration_ms < 1000 * {{slow_seconds}},0,1) as slow
| sum(slow) as slow_searches by _timeslice,query_type | transpose row _timeslice column query_type

_view=sumologic_search_usage_per_query {{{filter}}}
//| where execution_duration_ms > 30000
| (query_end_time - query_start_time)/1000 as range_s
| execution_duration_ms /1000 as duration_s
| if(execution_duration_ms > 1000 * {{slow_seconds}},1,0) as slow
| if(status_message = "Finished successfully",0,1) as fail
// AGGREGATE TO GET STATS
| count_distinct(user_name) as users,count as searches,sum(data_scanned_bytes) as bytes_scanned , sum(slow) as %"slow > 30s", sum(fail) as %"fail/cancelled" by analytics_tier
| sort bytes_scanned
| bytes_scanned / 1024/1024/1024 as scan_gb | fields -bytes_scanned

_view=sumologic_search_usage_per_query {{{filter}}}
| where execution_duration_ms > (1000 * {{slow_seconds}})
//| timeslice by {{timeslice}}
|if(execution_duration_ms < 1000 * {{slow_seconds}},0,1) as slow
| sum(slow) as slow_searches by user_name //| transpose row _timeslice column user_name
| replace (user_name,/@.+/,"") as user_name 
| sort slow_searches

_view=sumologic_search_usage_per_query query_type="Interactive Dashboard"
//| where data_scanned_bytes > (1 * 1G)
//| (query_end_time - query_start_time)/1000 as range_s
//| execution_duration_ms /1000 as duration_s
| if(isempty(content_name),substring(query,0,200),content_name) as item
| if(status_message = "Finished successfully",0,1) as fail

| count_distinct(user_name) as users,count_distinct(query) as unique_queries,max(scanned_partition_count) as max_partitions,count_distinct(user_name) as user_list,count as searches, sum(data_scanned_bytes) as bytes_scanned,   sum(fail) as %"fail/cancelled" by item
//| replace (partitions,"\n",", ") as partitions
| sort users
| bytes_scanned / 1024/1024/1024/1024 as scan_tb
| fields -bytes_scanned,user_list,%"fail/cancelled",max_partitions

_view=sumologic_search_usage_per_query query_type="Interactive Dashboard"
//| where data_scanned_bytes > (1 * 1G)
//| (query_end_time - query_start_time)/1000 as range_s
//| execution_duration_ms /1000 as duration_s
| if(isempty(content_name),substring(query,0,200),content_name) as item
| if(status_message = "Finished successfully",0,1) as fail

| count_distinct(query) as unique_queries,max(scanned_partition_count) as max_partitions,count_distinct(user_name) as users,count as searches, sum(data_scanned_bytes) as bytes_scanned,   sum(fail) as %"fail/cancelled" by user_name,query_type,item
//| replace (partitions,"\n",", ") as partitions
| sort bytes_scanned
| bytes_scanned / 1024/1024/1024/1024 as scan_tb
| fields -bytes_scanned,unique_queries,users,query_type

